  var rb = sheet.querySelector("[data-wl-rboost]");
  rb.textContent = !ranked ? "Send them your link. They get early access too." : progress(r, f);
  rb.classList.toggle("wl-prog", ranked && (front || !!(f.sent || f.joined || f.pending)));
