  ty.querySelector(".wl-tn").setAttribute("aria-label", shown + " of " + GOAL + " friends joined");
  ty.querySelectorAll("[data-wl-dash] i").forEach(function (d, i) { var s = f.slots[i]; d.className = front || s.st === "st-joined" ? "j" : s.st === "st-empty" ? "" : "v"; });
